CREATE TABLE IF NOT EXISTS organizations (id uuid PRIMARY KEY, name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS businesses (id uuid PRIMARY KEY, organization_id uuid NOT NULL REFERENCES organizations(id), name text NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS business_offerings (id uuid PRIMARY KEY, business_id uuid NOT NULL REFERENCES businesses(id), name text NOT NULL, active boolean NOT NULL DEFAULT true, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS business_offering_revisions (id uuid PRIMARY KEY, offering_id uuid NOT NULL REFERENCES business_offerings(id), revision_number integer NOT NULL CHECK (revision_number > 0), name text NOT NULL, description text NOT NULL, pricing_kind text NOT NULL CHECK (pricing_kind IN ('fixed','unknown')), currency text, amount_minor integer, visibility text NOT NULL CHECK (visibility IN ('public','private')), approval_status text NOT NULL CHECK (approval_status IN ('draft','approved','rejected')), provenance_source_type text NOT NULL CHECK (provenance_source_type IN ('owner_input','imported_record','verified_external_source')), provenance_source_reference text NOT NULL, provenance_captured_at timestamptz NOT NULL, provenance_captured_by text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE (offering_id, id), UNIQUE (offering_id, revision_number), CHECK ((pricing_kind = 'fixed' AND currency ~ '^[A-Z]{3}$' AND amount_minor IS NOT NULL AND amount_minor >= 0) OR (pricing_kind = 'unknown' AND currency IS NULL AND amount_minor IS NULL)));
CREATE TABLE IF NOT EXISTS offering_publications (offering_id uuid PRIMARY KEY REFERENCES business_offerings(id), revision_id uuid NOT NULL UNIQUE, published_at timestamptz NOT NULL DEFAULT now(), FOREIGN KEY (offering_id, revision_id) REFERENCES business_offering_revisions(offering_id, id));
CREATE OR REPLACE FUNCTION kablet_assert_publishable_revision() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NOT EXISTS (SELECT 1 FROM business_offering_revisions r WHERE r.id = NEW.revision_id AND r.offering_id = NEW.offering_id AND r.approval_status = 'approved') THEN RAISE EXCEPTION 'only an approved revision belonging to the offering may be published'; END IF; RETURN NEW; END $$;
DROP TRIGGER IF EXISTS offering_publication_integrity ON offering_publications;
CREATE TRIGGER offering_publication_integrity BEFORE INSERT OR UPDATE ON offering_publications FOR EACH ROW EXECUTE FUNCTION kablet_assert_publishable_revision();
CREATE OR REPLACE FUNCTION kablet_protect_approved_revision() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF OLD.approval_status = 'approved' THEN RAISE EXCEPTION 'approved revisions are immutable'; END IF; RETURN COALESCE(NEW, OLD); END $$;
DROP TRIGGER IF EXISTS approved_revision_immutable ON business_offering_revisions;
CREATE TRIGGER approved_revision_immutable BEFORE UPDATE OR DELETE ON business_offering_revisions FOR EACH ROW EXECUTE FUNCTION kablet_protect_approved_revision();
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['organizations','businesses','business_offerings','business_offering_revisions','offering_publications'] LOOP EXECUTE format('ALTER TABLE %I ENABLE ROW LEVEL SECURITY', t); EXECUTE format('ALTER TABLE %I FORCE ROW LEVEL SECURITY', t); END LOOP; END $$;
CREATE OR REPLACE FUNCTION kablet_current_org() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT NULLIF(current_setting('kablet.organization_id', true), '')::uuid $$;
DROP POLICY IF EXISTS organization_isolation ON organizations; CREATE POLICY organization_isolation ON organizations USING (id = kablet_current_org()) WITH CHECK (id = kablet_current_org());
DROP POLICY IF EXISTS business_isolation ON businesses; CREATE POLICY business_isolation ON businesses USING (organization_id = kablet_current_org()) WITH CHECK (organization_id = kablet_current_org());
DROP POLICY IF EXISTS offering_isolation ON business_offerings; CREATE POLICY offering_isolation ON business_offerings USING (EXISTS (SELECT 1 FROM businesses b WHERE b.id = business_offerings.business_id AND b.organization_id = kablet_current_org())) WITH CHECK (EXISTS (SELECT 1 FROM businesses b WHERE b.id = business_offerings.business_id AND b.organization_id = kablet_current_org()));
DROP POLICY IF EXISTS revision_isolation ON business_offering_revisions; CREATE POLICY revision_isolation ON business_offering_revisions USING (EXISTS (SELECT 1 FROM business_offerings o JOIN businesses b ON b.id = o.business_id WHERE o.id = business_offering_revisions.offering_id AND b.organization_id = kablet_current_org())) WITH CHECK (EXISTS (SELECT 1 FROM business_offerings o JOIN businesses b ON b.id = o.business_id WHERE o.id = business_offering_revisions.offering_id AND b.organization_id = kablet_current_org()));
DROP POLICY IF EXISTS publication_isolation ON offering_publications; CREATE POLICY publication_isolation ON offering_publications USING (EXISTS (SELECT 1 FROM business_offerings o JOIN businesses b ON b.id = o.business_id WHERE o.id = offering_publications.offering_id AND b.organization_id = kablet_current_org())) WITH CHECK (EXISTS (SELECT 1 FROM business_offerings o JOIN businesses b ON b.id = o.business_id WHERE o.id = offering_publications.offering_id AND b.organization_id = kablet_current_org()));
